import { useEffect, useState } from "react";

export function useCursorPosition() {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (event: MouseEvent) => {
      setPosition({ x: event.clientX, y: event.clientY });
    };
    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  return position;
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { act, fireEvent, render } from "../../../test-utils/render";
import CursorImageTrail, { type CursorTrailImage } from "../index";

const images: CursorTrailImage[] = [
  { alt: "Sample one", src: "/images/one.jpg" },
  { alt: "Sample two", src: "/images/two.jpg" },
];

type MockMediaQueryList = {
  addEventListener: (type: string, handler: () => void) => void;
  addListener: () => void;
  dispatchEvent: () => boolean;
  matches: boolean;
  media: string;
  onchange: null;
  removeEventListener: () => void;
  removeListener: () => void;
  _changeHandler?: () => void;
};

// `motion`'s useReducedMotion() reads window.matchMedia("(prefers-reduced-motion)")
// exactly once per test file (module-level singleton in motion-dom), the first
// time any component in this file calls the hook, and only ever updates
// afterwards via a "change" event dispatched on that original MediaQueryList.
// Reassigning window.matchMedia in a later test has no effect on that cached
// value, so we capture the very first reduced-motion query object here and,
// when a test needs reduced motion to be "on", flip its `matches` flag and
// invoke the handler motion-dom itself registered.
let reducedMotionRecord: MockMediaQueryList | null = null;

const mockMatchMedia = (hoverMatches: boolean) => {
  window.matchMedia = vi.fn().mockImplementation((query: string) => {
    const isReducedMotionQuery = query.includes("prefers-reduced-motion");
    const record: MockMediaQueryList = {
      addEventListener: (type, handler) => {
        if (type === "change") {
          record._changeHandler = handler;
        }
      },
      addListener: () => {},
      dispatchEvent: () => false,
      matches: isReducedMotionQuery ? false : hoverMatches,
      media: query,
      onchange: null,
      removeEventListener: () => {},
      removeListener: () => {},
    };
    if (isReducedMotionQuery && !reducedMotionRecord) {
      reducedMotionRecord = record;
    }
    return record;
  });
};

const forceReducedMotion = () => {
  if (!reducedMotionRecord) {
    throw new Error(
      "reducedMotionRecord was never captured; render a CursorImageTrail first"
    );
  }
  reducedMotionRecord.matches = true;
  reducedMotionRecord._changeHandler?.();
};

let scheduled: Map<number, FrameRequestCallback>;
let nextFrameId: number;
let currentTime: number;

const stubTiming = () => {
  scheduled = new Map();
  nextFrameId = 1;
  currentTime = 0;
  vi.stubGlobal(
    "requestAnimationFrame",
    vi.fn((cb: FrameRequestCallback) => {
      const id = nextFrameId++;
      scheduled.set(id, cb);
      return id;
    })
  );
  vi.stubGlobal(
    "cancelAnimationFrame",
    vi.fn((id: number) => {
      scheduled.delete(id);
    })
  );
  vi.spyOn(performance, "now").mockImplementation(() => currentTime);
};

// Runs whichever frame is currently queued at an *absolute* clock time,
// giving exact control over `elapsed = now - slot.startTime` for lifetime
// decay assertions.
const runFrameAt = (absoluteTime: number) => {
  currentTime = absoluteTime;
  const pending = Array.from(scheduled.entries());
  scheduled.clear();
  act(() => {
    for (const [, cb] of pending) {
      cb(currentTime);
    }
  });
};

describe("CursorImageTrail", () => {
  beforeEach(() => {
    stubTiming();
    mockMatchMedia(true);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(
      <CursorImageTrail images={images} poolSize={2}>
        <p>Hover area</p>
      </CursorImageTrail>
    );
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("renders without throwing", () => {
    const { container } = render(
      <CursorImageTrail images={images}>
        <p>Hover area</p>
      </CursorImageTrail>
    );
    expect(container).toBeInTheDocument();
  });

  it("only spawns once the pointer has moved past `distance`", () => {
    const { container } = render(
      <CursorImageTrail distance={40} images={images} poolSize={2}>
        <p>Hover area</p>
      </CursorImageTrail>
    );
    const root = container.firstChild as HTMLElement;
    const img = container.querySelector("img") as HTMLImageElement;

    fireEvent.pointerEnter(root, { clientX: 0, clientY: 0 });
    runFrameAt(10); // Establishes the spawn baseline; no spawn yet.

    fireEvent.pointerMove(root, { clientX: 10, clientY: 0 });
    runFrameAt(20); // Only moved 10px, under the 40px threshold.

    expect(img.getAttribute("src")).toContain("one.jpg");

    fireEvent.pointerMove(root, { clientX: 50, clientY: 0 });
    runFrameAt(30); // Now 50px from baseline, past the threshold: spawns.

    // The spawned slot's transform is stamped with the spawn position.
    expect(img.style.transform).toContain("translate3d(50px, 0px, 0)");
  });

  it("recycles pool slots instead of growing the DOM when spawns exceed poolSize", () => {
    const { container } = render(
      <CursorImageTrail distance={10} images={images} poolSize={3}>
        <p>Hover area</p>
      </CursorImageTrail>
    );
    const root = container.firstChild as HTMLElement;

    const imagesBefore = Array.from(container.querySelectorAll("img"));
    expect(imagesBefore).toHaveLength(3);

    fireEvent.pointerEnter(root, { clientX: 0, clientY: 0 });
    runFrameAt(10);

    // 4 spawns on a pool of 3: the 4th must recycle slot 0.
    for (let i = 1; i <= 4; i++) {
      fireEvent.pointerMove(root, { clientX: i * 100, clientY: 0 });
      runFrameAt(10 + i * 10);
    }

    const imagesAfter = Array.from(container.querySelectorAll("img"));
    // Same node count, and the very same DOM nodes: the pool never grows.
    expect(imagesAfter).toHaveLength(3);
    expect(imagesAfter).toEqual(imagesBefore);

    // Slot 0 held image[0] after spawn 1, then got recycled by spawn 4
    // (spawn index 3 % poolSize 3 === 0) and now holds image[1].
    expect(imagesAfter[0].getAttribute("src")).toContain("two.jpg");
  });

  it("fades a spawned trail image in, holds it, then fades and clears it over its lifetime", () => {
    const { container } = render(
      <CursorImageTrail
        distance={10}
        images={images}
        lifetime={100}
        poolSize={1}
        velocityScale={0}
      >
        <p>Hover area</p>
      </CursorImageTrail>
    );
    const root = container.firstChild as HTMLElement;
    const img = container.querySelector("img") as HTMLImageElement;

    fireEvent.pointerEnter(root, { clientX: 0, clientY: 0 });
    runFrameAt(10); // Baseline, no spawn.

    fireEvent.pointerMove(root, { clientX: 50, clientY: 0 });
    runFrameAt(20); // Spawns at startTime=20, elapsed=0 in the same tick.
    expect(img.style.opacity).toBe("0");

    runFrameAt(30); // elapsed=10, progress=0.1 (entering: 0 < opacity < 1).
    const entering = Number(img.style.opacity);
    expect(entering).toBeGreaterThan(0);
    expect(entering).toBeLessThan(1);

    runFrameAt(60); // elapsed=40, progress=0.4 (steady phase).
    expect(img.style.opacity).toBe("1");

    runFrameAt(100); // elapsed=80, progress=0.8 (exiting: fading back out).
    const exiting = Number(img.style.opacity);
    expect(exiting).toBeGreaterThan(0);
    expect(exiting).toBeLessThan(1);

    runFrameAt(130); // elapsed=110 > lifetime: slot deactivates and clears.
    expect(img.style.opacity).toBe("0");
  });

  // NOTE: this test permanently flips motion's cached reduced-motion
  // singleton for the rest of this file (see the comment above
  // `reducedMotionRecord`), so it must stay last in this describe block.
  it("skips the trail pool entirely, and ignores pointer movement, once reduced motion is preferred", () => {
    forceReducedMotion();

    const { container } = render(
      <CursorImageTrail images={images}>
        <p>Hover area</p>
      </CursorImageTrail>
    );
    const root = container.firstChild as HTMLElement;

    // `effectEnabled` is false, so the pool markup that owns the trail
    // listeners is never mounted in the first place.
    expect(container.querySelectorAll("img")).toHaveLength(0);

    // Confirms the effect's early return: without the pool, pointer
    // movement that would otherwise spawn trail images is a pure no-op.
    fireEvent.pointerEnter(root, { clientX: 0, clientY: 0 });
    fireEvent.pointerMove(root, { clientX: 200, clientY: 0 });
    expect(container.querySelectorAll("img")).toHaveLength(0);
  });
});

"use client";

import { cn } from "@repo/smoothui-utils";
import { useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

export interface CursorTrailImage {
  alt: string;
  src: string;
}

export interface CursorImageTrailProps {
  children: ReactNode;
  className?: string;
  distance?: number;
  imageSize?: number;
  images: CursorTrailImage[];
  lifetime?: number;
  poolSize?: number;
  rotate?: number;
  velocityScale?: number;
}

interface TrailSlot {
  active: boolean;
  duration: number;
  rotation: number;
  scale: number;
  startTime: number;
  x: number;
  y: number;
}

const DEFAULT_POOL_SIZE = 12;
const DEFAULT_DISTANCE = 90;
const DEFAULT_LIFETIME = 700;
const DEFAULT_ROTATE = 12;
const DEFAULT_VELOCITY_SCALE = 0.5;
const DEFAULT_IMAGE_SIZE = 96;
const ENTER_RATIO = 0.25;
const EXIT_RATIO = 0.35;
const MAX_FRAME_DELTA_MS = 50;

const easeOutQuint = (t: number) => 1 - (1 - t) ** 5;
const easeInOutCubic = (t: number) =>
  t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

const createSlots = (poolSize: number, lifetime: number): TrailSlot[] =>
  Array.from({ length: poolSize }, () => ({
    active: false,
    duration: lifetime,
    rotation: 0,
    scale: 1,
    startTime: 0,
    x: 0,
    y: 0,
  }));

const CursorImageTrail = ({
  children,
  className,
  distance = DEFAULT_DISTANCE,
  imageSize = DEFAULT_IMAGE_SIZE,
  images,
  lifetime = DEFAULT_LIFETIME,
  poolSize = DEFAULT_POOL_SIZE,
  rotate = DEFAULT_ROTATE,
  velocityScale = DEFAULT_VELOCITY_SCALE,
}: CursorImageTrailProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const slotRefs = useRef<(HTMLImageElement | null)[]>([]);
  const slotStateRef = useRef<TrailSlot[]>(createSlots(poolSize, lifetime));
  const pointerRef = useRef<{ x: number; y: number } | null>(null);
  const isInsideRef = useRef(false);
  const lastFrameRef = useRef<{ t: number; x: number; y: number } | null>(null);
  const lastSpawnRef = useRef<{ x: number; y: number } | null>(null);
  const nextSlotRef = useRef(0);
  const nextImageRef = useRef(0);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mediaQuery.matches);

    const handleChange = (event: MediaQueryListEvent) => {
      setIsHoverDevice(event.matches);
    };

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const effectEnabled =
    isHoverDevice && !shouldReduceMotion && images.length > 0;

  useEffect(() => {
    if (!effectEnabled) {
      return;
    }

    const container = containerRef.current;
    if (!container) {
      return;
    }

    slotStateRef.current = createSlots(poolSize, lifetime);
    nextSlotRef.current = 0;
    nextImageRef.current = 0;
    lastFrameRef.current = null;
    lastSpawnRef.current = null;

    const spawn = (x: number, y: number, velocity: number) => {
      const slotIndex = nextSlotRef.current % poolSize;
      nextSlotRef.current += 1;
      const imageIndex = nextImageRef.current % images.length;
      nextImageRef.current += 1;

      const image = images[imageIndex];
      const el = slotRefs.current[slotIndex];
      if (!(el && image)) {
        return;
      }

      el.src = image.src;
      el.alt = image.alt;

      const speedFactor = clamp(velocity * velocityScale, 0, 1);
      const rotation = (Math.random() * 2 - 1) * rotate;

      slotStateRef.current[slotIndex] = {
        active: true,
        duration: lifetime * (1 + speedFactor * 0.6),
        rotation,
        scale: 1 + speedFactor * 0.5,
        startTime: performance.now(),
        x,
        y,
      };
    };

    const tick = (now: number) => {
      if (pointerRef.current && isInsideRef.current) {
        const rect = container.getBoundingClientRect();
        const x = pointerRef.current.x - rect.left;
        const y = pointerRef.current.y - rect.top;

        let velocity = 0;
        if (lastFrameRef.current) {
          const dt = Math.min(now - lastFrameRef.current.t, MAX_FRAME_DELTA_MS);
          if (dt > 0) {
            const dx = x - lastFrameRef.current.x;
            const dy = y - lastFrameRef.current.y;
            velocity = Math.hypot(dx, dy) / dt;
          }
        }
        lastFrameRef.current = { t: now, x, y };

        if (lastSpawnRef.current) {
          const dx = x - lastSpawnRef.current.x;
          const dy = y - lastSpawnRef.current.y;
          if (Math.hypot(dx, dy) >= distance) {
            spawn(x, y, velocity);
            lastSpawnRef.current = { x, y };
          }
        } else {
          lastSpawnRef.current = { x, y };
        }
      }

      for (let i = 0; i < slotStateRef.current.length; i++) {
        const slot = slotStateRef.current[i];
        const el = slotRefs.current[i];
        if (!(slot?.active && el)) {
          continue;
        }

        const elapsed = now - slot.startTime;
        const progress = clamp(elapsed / slot.duration, 0, 1);

        let opacity: number;
        let scale: number;

        if (progress <= ENTER_RATIO) {
          const enterProgress = progress / ENTER_RATIO;
          const eased = easeOutQuint(enterProgress);
          opacity = eased;
          scale = eased * slot.scale;
        } else if (progress >= 1 - EXIT_RATIO) {
          const exitProgress = (progress - (1 - EXIT_RATIO)) / EXIT_RATIO;
          const eased = easeInOutCubic(exitProgress);
          opacity = 1 - eased;
          scale = slot.scale * (1 - eased * 0.15);
        } else {
          opacity = 1;
          ({ scale } = slot);
        }

        el.style.transform = `translate3d(${slot.x}px, ${slot.y}px, 0) translate(-50%, -50%) rotate(${slot.rotation}deg) scale(${scale})`;
        el.style.opacity = String(opacity);

        if (progress >= 1) {
          slot.active = false;
          el.style.opacity = "0";
        }
      }

      rafRef.current = requestAnimationFrame(tick);
    };

    const handlePointerMove = (event: PointerEvent) => {
      pointerRef.current = { x: event.clientX, y: event.clientY };
      isInsideRef.current = true;
    };
    const handlePointerEnter = (event: PointerEvent) => {
      pointerRef.current = { x: event.clientX, y: event.clientY };
      isInsideRef.current = true;
      lastSpawnRef.current = null;
      lastFrameRef.current = null;
    };
    const handlePointerLeave = () => {
      isInsideRef.current = false;
    };

    container.addEventListener("pointermove", handlePointerMove);
    container.addEventListener("pointerenter", handlePointerEnter);
    container.addEventListener("pointerleave", handlePointerLeave);
    rafRef.current = requestAnimationFrame(tick);

    return () => {
      container.removeEventListener("pointermove", handlePointerMove);
      container.removeEventListener("pointerenter", handlePointerEnter);
      container.removeEventListener("pointerleave", handlePointerLeave);
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = null;
      }
    };
  }, [
    effectEnabled,
    images,
    poolSize,
    lifetime,
    distance,
    rotate,
    velocityScale,
  ]);

  return (
    <div
      className={cn("relative overflow-hidden", className)}
      ref={containerRef}
    >
      {children}
      {effectEnabled ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 select-none"
        >
          {Array.from({ length: poolSize }).map((_, index) => (
            <img
              alt=""
              className="absolute top-0 left-0 rounded-xl object-cover opacity-0 shadow-lg will-change-transform"
              draggable={false}
              // biome-ignore lint/suspicious/noArrayIndexKey: pool slots are positional and never reorder
              key={index}
              ref={(el) => {
                slotRefs.current[index] = el;
              }}
              src={images[0]?.src}
              style={{ height: imageSize, width: imageSize }}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
};

