const StaggerChild = ({
  children,
  index,
  shouldReduceMotion,
}: {
  children: ReactNode;
  index: number;
  shouldReduceMotion: boolean | null;
}) => (
  <motion.div
    animate={
      shouldReduceMotion
        ? { opacity: 1 }
        : { opacity: 1, transform: "translateY(0px)" }
    }
    exit={
      shouldReduceMotion
        ? { opacity: 0, transition: { duration: 0 } }
        : {
            opacity: 0,
            transform: "translateY(4px)",
            transition: { duration: 0.12 },
          }
    }
    initial={
      shouldReduceMotion
        ? { opacity: 1 }
        : { opacity: 0, transform: "translateY(8px)" }
    }
    transition={
      shouldReduceMotion
        ? { duration: 0 }
        : {
            bounce: 0,
            delay: index * STAGGER_DELAY,
            duration: 0.25,
            type: "spring" as const,
          }
    }
  >
    {children}
  </motion.div>
);

const AnimatedCloseButton = ({
  shouldReduceMotion,
}: {
  shouldReduceMotion: boolean | null;
}) => (
  <DialogPrimitive.Close
    aria-label="Close dialog"
    className="absolute top-4 right-4 cursor-pointer rounded-xs opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none"
    render={
      <motion.button
        transition={{ duration: shouldReduceMotion ? 0 : 0.2 }}
        type="button"
        whileHover={shouldReduceMotion ? {} : { rotate: 90 }}
      />
    }
  >
    <X aria-hidden="true" className="pointer-events-none size-4 shrink-0" />
    <span className="sr-only">Close</span>
  </DialogPrimitive.Close>
);

type TriggerComponent = (props: {
  children?: ReactNode;
  nativeButton?: boolean;
  render?: ReactElement;
}) => ReactElement | null;

const renderTrigger = (Trigger: TriggerComponent, trigger: ReactNode) => {
  if (!trigger) {
    return null;
  }
  if (isValidElement(trigger)) {
    const element = trigger as ReactElement;
    const nativeButton =
      typeof element.type === "string" ? element.type === "button" : true;
    return <Trigger nativeButton={nativeButton} render={element} />;
  }
  return <Trigger>{trigger}</Trigger>;
};

const useDialogOpenState = (
  open: boolean | undefined,
  onOpenChange?: (open: boolean) => void
) => {
  const [internalOpen, setInternalOpen] = useState(false);
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const handleOpenChange = useCallback(
    (next: boolean) => {
      if (!isControlled) {
        setInternalOpen(next);
      }
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange]
  );

  const [showContent, setShowContent] = useState(false);
  const prevOpenRef = useRef(false);

  useEffect(() => {
    if (isOpen && !prevOpenRef.current) {
      setShowContent(true);
    }
    prevOpenRef.current = !!isOpen;
  }, [isOpen]);

  const handleAnimationComplete = useCallback(() => {
    if (!isOpen) {
      setShowContent(false);
    }
  }, [isOpen]);

  return {
    handleAnimationComplete,
    handleOpenChange,
    isOpen,
    setShowContent,
    showContent,
  };
};

/* ------------------------------------------------------------------ */
/*  Dialog                                                             */
/* ------------------------------------------------------------------ */

/**
 * SmoothUI Dialog — Base UI twin (default).
 * Same public props as the Radix twin; headless via `@base-ui/react/dialog`.
 */
export default function Dialog({
  open,
  onOpenChange,
  title,
  description,
  showCloseButton = true,
  className,
  children,
  trigger,
  footer,
}: DialogProps) {
  const shouldReduceMotion = useReducedMotion();
  const {
    isOpen,
    showContent,
    handleOpenChange,
    handleAnimationComplete,
    setShowContent,
  } = useDialogOpenState(open, onOpenChange);

  return (
    <DialogPrimitive.Root
      onOpenChange={handleOpenChange}
      open={isOpen || showContent}
    >
      {renderTrigger(DialogPrimitive.Trigger, trigger)}

      <AnimatePresence onExitComplete={() => setShowContent(false)}>
        {isOpen ? (
          <DialogPrimitive.Portal keepMounted>
            <DialogPrimitive.Backdrop
              className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm"
              data-slot="dialog-overlay"
              render={
                <motion.div
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0 }}
                  transition={{
                    duration: shouldReduceMotion ? 0 : DURATION.fast + 0.05,
                  }}
                />
              }
            />

            <DialogPrimitive.Popup
              className={cn(PANEL_CLASS, className)}
              data-slot="dialog-content"
              render={
                <motion.div
                  animate={
                    shouldReduceMotion ? { opacity: 1 } : { ...OVERLAY_ENTER }
                  }
                  exit={
                    shouldReduceMotion
                      ? { opacity: 0, transition: { duration: 0 } }
                      : { ...OVERLAY_EXIT, transition: { duration: 0.15 } }
                  }
                  initial={
                    shouldReduceMotion
                      ? { ...OVERLAY_ENTER }
                      : { ...OVERLAY_ENTER_INITIAL }
                  }
                  onAnimationComplete={handleAnimationComplete}
                  transition={
                    shouldReduceMotion ? { duration: 0 } : OVERLAY_TRANSITION
                  }
                />
              }
            >
              {title || description ? (
                <StaggerChild index={0} shouldReduceMotion={shouldReduceMotion}>
                  <DialogHeader>
                    {title ? <DialogTitle>{title}</DialogTitle> : null}
                    {description ? (
                      <DialogDescription>{description}</DialogDescription>
                    ) : null}
                  </DialogHeader>
                </StaggerChild>
              ) : null}

              {children ? (
                <StaggerChild
                  index={title || description ? 1 : 0}
                  shouldReduceMotion={shouldReduceMotion}
                >
                  {children}
                </StaggerChild>
              ) : null}

              {footer ? (
                <StaggerChild
                  index={(title || description ? 1 : 0) + (children ? 1 : 0)}
                  shouldReduceMotion={shouldReduceMotion}
                >
                  <DialogFooter>{footer}</DialogFooter>
                </StaggerChild>
              ) : null}

              {showCloseButton ? (
                <AnimatedCloseButton shouldReduceMotion={shouldReduceMotion} />
              ) : null}
            </DialogPrimitive.Popup>
          </DialogPrimitive.Portal>
        ) : null}
      </AnimatePresence>
    </DialogPrimitive.Root>
  );
}

/* ------------------------------------------------------------------ */
/*  AlertDialog                                                        */
/* ------------------------------------------------------------------ */

export function AlertDialog({
  open,
  onOpenChange,
  title,
  description,
  className,
  children,
  trigger,
  footer,
}: AlertDialogProps) {
  const shouldReduceMotion = useReducedMotion();
  const {
    isOpen,
    showContent,
    handleOpenChange,
    handleAnimationComplete,
    setShowContent,
  } = useDialogOpenState(open, onOpenChange);

  return (
    <AlertDialogPrimitive.Root
      onOpenChange={handleOpenChange}
      open={isOpen || showContent}
    >
      {renderTrigger(AlertDialogPrimitive.Trigger, trigger)}

      <AnimatePresence onExitComplete={() => setShowContent(false)}>
        {isOpen ? (
          <AlertDialogPrimitive.Portal keepMounted>
            <AlertDialogPrimitive.Backdrop
              className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm"
              data-slot="alert-dialog-overlay"
              render={
                <motion.div
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0 }}
                  transition={{
                    duration: shouldReduceMotion ? 0 : DURATION.fast + 0.05,
                  }}
                />
              }
            />

            <AlertDialogPrimitive.Popup
              className={cn(PANEL_CLASS, className)}
              data-slot="alert-dialog-content"
              render={
                <motion.div
                  animate={
                    shouldReduceMotion ? { opacity: 1 } : { ...OVERLAY_ENTER }
                  }
                  exit={
                    shouldReduceMotion
                      ? { opacity: 0, transition: { duration: 0 } }
                      : { ...OVERLAY_EXIT, transition: { duration: 0.15 } }
                  }
                  initial={
                    shouldReduceMotion
                      ? { ...OVERLAY_ENTER }
                      : { ...OVERLAY_ENTER_INITIAL }
                  }
                  onAnimationComplete={handleAnimationComplete}
                  transition={
                    shouldReduceMotion ? { duration: 0 } : OVERLAY_TRANSITION
                  }
                />
              }
            >
              {title || description ? (
                <StaggerChild index={0} shouldReduceMotion={shouldReduceMotion}>
                  <AlertDialogHeader>
                    {title ? (
                      <AlertDialogTitle>{title}</AlertDialogTitle>
                    ) : null}
                    {description ? (
                      <AlertDialogDescription>
                        {description}
                      </AlertDialogDescription>
                    ) : null}
                  </AlertDialogHeader>
                </StaggerChild>
              ) : null}

              {children ? (
                <StaggerChild
                  index={title || description ? 1 : 0}
                  shouldReduceMotion={shouldReduceMotion}
                >
                  {children}
                </StaggerChild>
              ) : null}

              {footer ? (
                <StaggerChild
                  index={(title || description ? 1 : 0) + (children ? 1 : 0)}
                  shouldReduceMotion={shouldReduceMotion}
                >
                  <AlertDialogFooter>{footer}</AlertDialogFooter>
                </StaggerChild>
              ) : null}
            </AlertDialogPrimitive.Popup>
          </AlertDialogPrimitive.Portal>
        ) : null}
      </AnimatePresence>
    </AlertDialogPrimitive.Root>
  );
}

