import { createRef } from "react";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import {
  type Canvas2DMock,
  flushFrame,
  flushFrames,
  installCanvas2DMock,
  pendingFrameCount,
  runFramesFor,
  uninstallCanvas2DMock,
} from "../../../test-utils/canvas-2d";
import { act, render } from "../../../test-utils/render";
import DrawingCursor, { type DrawingCursorHandle } from "../index";

const SIZE = 200;

describe("DrawingCursor", () => {
  it("has no accessibility violations", async () => {
    const { container } = render(
      <DrawingCursor>
        <p>Draw over this area</p>
      </DrawingCursor>
    );
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("renders without throwing", () => {
    const { container } = render(
      <DrawingCursor>
        <p>Draw over this area</p>
      </DrawingCursor>
    );
    expect(container).toBeInTheDocument();
  });
});

describe("DrawingCursor draw loop", () => {
  let canvas2d: Canvas2DMock;

  beforeEach(() => {
    canvas2d = installCanvas2DMock({ height: SIZE, width: SIZE });
  });

  afterEach(() => {
    uninstallCanvas2DMock();
  });

  const setup = (props: Parameters<typeof DrawingCursor>[0] = {}) => {
    const result = render(
      <DrawingCursor {...props}>
        <p>Draw over this area</p>
      </DrawingCursor>
    );
    const host = result.container.firstElementChild as HTMLElement;
    const canvas = result.container.querySelector("canvas");
    return {
      ...result,
      canvas,
      context: canvas ? canvas2d.contextFor(canvas) : undefined,
      host,
    };
  };

  /** Moves the pointer to a point, timestamped with the mocked clock. */
  const move = (host: HTMLElement, x: number, y: number) => {
    act(() => {
      host.dispatchEvent(
        new PointerEvent("pointermove", {
          bubbles: true,
          clientX: x,
          clientY: y,
        })
      );
    });
  };

  it("sizes the canvas from the container and starts the loop", () => {
    const { context } = setup();
    expect(context?.setTransform).toHaveBeenCalledWith(1, 0, 0, 1, 0, 0);
    expect(pendingFrameCount()).toBeGreaterThan(0);
  });

  it("clears the surface on every frame", () => {
    const { context } = setup();
    context?.resetRecords();

    flushFrames(3);

    expect(context?.clearRect).toHaveBeenCalledTimes(3);
    expect(context?.globalCompositeOperation).toBe("source-over");
  });

  it("strokes a straight segment for a two-point stroke", () => {
    const { context, host } = setup();
    move(host, 10, 10);
    move(host, 20, 30);
    context?.resetRecords();

    flushFrame();

    expect(context?.moveTo).toHaveBeenCalledWith(10, 10);
    expect(context?.lineTo).toHaveBeenCalledWith(20, 30);
    expect(context?.stroke).toHaveBeenCalledTimes(1);
    expect(context?.quadraticCurveTo).not.toHaveBeenCalled();
  });

  it("smooths a longer stroke through quadratic curves", () => {
    const { context, host } = setup();
    move(host, 10, 10);
    move(host, 30, 20);
    move(host, 50, 40);
    move(host, 70, 30);
    context?.resetRecords();

    flushFrame();

    expect(context?.quadraticCurveTo).toHaveBeenCalledTimes(2);
    expect(context?.stroke).toHaveBeenCalledTimes(2);
  });

  it("prefers coalesced pointer samples when the browser provides them", () => {
    const { context, host } = setup();

    act(() => {
      const event = new PointerEvent("pointermove", {
        bubbles: true,
        clientX: 90,
        clientY: 90,
      });
      Object.defineProperty(event, "getCoalescedEvents", {
        value: () => [
          { clientX: 10, clientY: 10 },
          { clientX: 40, clientY: 45 },
        ],
      });
      host.dispatchEvent(event);
    });
    context?.resetRecords();

    flushFrame();

    expect(context?.moveTo).toHaveBeenCalledWith(10, 10);
    expect(context?.lineTo).toHaveBeenCalledWith(40, 45);
  });

  it("keeps a constant line width when tapering is off", () => {
    const { context, host } = setup({ lineWidth: 6, taper: false });
    move(host, 10, 10);
    move(host, 90, 90);
    context?.resetRecords();

    flushFrame();

    expect(context?.lineWidth).toBe(6);
  });

  it("lets a stroke decay out of the buffer", () => {
    const { context, host } = setup({ decay: 200 });
    move(host, 10, 10);
    move(host, 40, 40);
    move(host, 70, 70);

    flushFrame();
    expect(context?.stroke).toHaveBeenCalled();

    runFramesFor(400);
    context?.resetRecords();
    flushFrame();

    expect(context?.stroke).not.toHaveBeenCalled();
  });

  it("keeps every point when decay is disabled", () => {
    const { context, host } = setup({ decay: 0 });
    move(host, 10, 10);
    move(host, 40, 40);
    move(host, 70, 70);

    runFramesFor(2000);
    context?.resetRecords();
    flushFrame();

    expect(context?.stroke).toHaveBeenCalled();
  });

  it("drops the strokes when the pointer leaves", () => {
    const { context, host } = setup();
    move(host, 10, 10);
    move(host, 40, 40);
    move(host, 70, 70);

    act(() => {
      host.dispatchEvent(new PointerEvent("pointerleave", { bubbles: true }));
    });
    context?.resetRecords();
    flushFrame();

    expect(context?.stroke).not.toHaveBeenCalled();
  });

  it("keeps the strokes on leave when clearOnLeave is off", () => {
    const { context, host } = setup({ clearOnLeave: false });
    move(host, 10, 10);
    move(host, 40, 40);
    move(host, 70, 70);

    act(() => {
      host.dispatchEvent(new PointerEvent("pointerleave", { bubbles: true }));
    });
    context?.resetRecords();
    flushFrame();

    expect(context?.stroke).toHaveBeenCalled();
  });

  it("never schedules a frame while paused", () => {
    const { context } = setup({ paused: true });
    expect(pendingFrameCount()).toBe(0);
    expect(context?.clearRect).not.toHaveBeenCalled();
  });

  it("clears and exports through the ref", () => {
    const ref = createRef<DrawingCursorHandle>();
    const { context, host } = setup({ ref });
    move(host, 10, 10);
    move(host, 40, 40);
    move(host, 70, 70);

    expect(ref.current?.toDataURL()).toMatch(/^data:image\/png/);

    act(() => {
      ref.current?.clear();
    });
    context?.resetRecords();
    flushFrame();

    expect(context?.stroke).not.toHaveBeenCalled();
  });

  it("cancels the loop on unmount", () => {
    const { unmount } = setup();
    flushFrame();
    expect(pendingFrameCount()).toBeGreaterThan(0);

    unmount();
    expect(pendingFrameCount()).toBe(0);
  });
});

describe("DrawingCursor without a fine pointer", () => {
  afterEach(() => {
    uninstallCanvas2DMock();
  });

  it("mounts no canvas on a coarse pointer", () => {
    installCanvas2DMock({ matchMedia: () => false });
    const { container } = render(<DrawingCursor />);
    expect(container.querySelector("canvas")).toBeNull();
  });
});

"use client";

import { cn } from "@repo/smoothui-utils";
import { useReducedMotion } from "motion/react";
import type { ReactNode, Ref } from "react";
import { useEffect, useImperativeHandle, useRef, useState } from "react";

export type DrawingCursorHandle = {
  clear: () => void;
  toDataURL: (type?: string, quality?: number) => string;
};

export type DrawingCursorProps = {
  blend?: GlobalCompositeOperation;
  children?: ReactNode;
  className?: string;
  clearOnLeave?: boolean;
  color?: string;
  decay?: number;
  lineWidth?: number;
  paused?: boolean;
  ref?: Ref<DrawingCursorHandle>;
  smoothing?: number;
  taper?: boolean;
};

type StrokePoint = { time: number; width: number; x: number; y: number };
type Stroke = { points: StrokePoint[] };

const DEFAULT_COLOR = "var(--color-brand, #6366f1)";
const DEFAULT_LINE_WIDTH = 3;
const DEFAULT_DECAY = 800;
const DEFAULT_SMOOTHING = 0.5;
const MAX_DEVICE_PIXEL_RATIO = 2;
const STROKE_BREAK_MS = 120;
const MIN_WIDTH_FACTOR = 0.35;
const SPEED_TO_WIDTH_SCALE = 0.12;
const MAX_POINTS_PER_STROKE = 600;
const MAX_STROKES = 40;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const getPointerCoordinates = (
  event: PointerEvent,
  rect: DOMRect
): { x: number; y: number }[] => {
  const coalesced =
    typeof event.getCoalescedEvents === "function"
      ? event.getCoalescedEvents()
      : null;
  const events = coalesced && coalesced.length > 0 ? coalesced : [event];
  return events.map((coalescedEvent) => ({
    x: coalescedEvent.clientX - rect.left,
    y: coalescedEvent.clientY - rect.top,
  }));
};

const DrawingCursor = ({
  blend = "source-over",
  children,
  className,
  clearOnLeave = true,
  color = DEFAULT_COLOR,
  decay = DEFAULT_DECAY,
  lineWidth = DEFAULT_LINE_WIDTH,
  paused = false,
  ref,
  smoothing = DEFAULT_SMOOTHING,
  taper = true,
}: DrawingCursorProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isPointerCapable, setIsPointerCapable] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const strokesRef = useRef<Stroke[]>([]);
  const activeStrokeRef = useRef<Stroke | null>(null);
  const rafRef = useRef<number | null>(null);
  const sizeRef = useRef({ height: 0, width: 0 });

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsPointerCapable(mediaQuery.matches);
    const handleChange = (event: MediaQueryListEvent) => {
      setIsPointerCapable(event.matches);
    };
    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const isMounted = isPointerCapable && !shouldReduceMotion;

  useImperativeHandle(
    ref,
    () => ({
      clear: () => {
        strokesRef.current = [];
        activeStrokeRef.current = null;
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext("2d");
        if (canvas && ctx) {
          ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
      },
      toDataURL: (type?: string, quality?: number) =>
        canvasRef.current?.toDataURL(type, quality) ?? "",
    }),
    []
  );

  useEffect(() => {
    if (!isMounted) {
      return;
    }
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!(container && canvas)) {
      return;
    }
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      return;
    }

    const resize = () => {
      const rect = container.getBoundingClientRect();
      const dpr = Math.min(
        window.devicePixelRatio || 1,
        MAX_DEVICE_PIXEL_RATIO
      );
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sizeRef.current = { height: rect.height, width: rect.width };
    };

    resize();
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(container);

    let lastPointTime = 0;

    const pushPoint = (x: number, y: number, time: number) => {
      const isNewStroke =
        !activeStrokeRef.current || time - lastPointTime > STROKE_BREAK_MS;
      if (isNewStroke) {
        const stroke: Stroke = { points: [] };
        activeStrokeRef.current = stroke;
        strokesRef.current.push(stroke);
        if (strokesRef.current.length > MAX_STROKES) {
          strokesRef.current.shift();
        }
      }
      const stroke = activeStrokeRef.current;
      if (!stroke) {
        return;
      }
      const previous = stroke.points.at(-1);
      let width = lineWidth;
      if (taper && previous) {
        const dt = Math.max(1, time - previous.time);
        const distance = Math.hypot(x - previous.x, y - previous.y);
        const speed = distance / dt;
        const factor = clamp(
          1 - speed * SPEED_TO_WIDTH_SCALE,
          MIN_WIDTH_FACTOR,
          1
        );
        width = lineWidth * factor;
      }
      stroke.points.push({ time, width, x, y });
      if (stroke.points.length > MAX_POINTS_PER_STROKE) {
        stroke.points.shift();
      }
      lastPointTime = time;
    };

    const handlePointerMove = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      const coordinates = getPointerCoordinates(event, rect);
      for (const point of coordinates) {
        pushPoint(point.x, point.y, performance.now());
      }
    };

    const handlePointerLeave = () => {
      activeStrokeRef.current = null;
      if (clearOnLeave) {
        strokesRef.current = [];
        ctx.clearRect(0, 0, canvas.width, canvas.height);
      }
    };

    container.addEventListener("pointermove", handlePointerMove, {
      passive: true,
    });
    container.addEventListener("pointerleave", handlePointerLeave, {
      passive: true,
    });

    const drawStroke = (stroke: Stroke, now: number) => {
      const { points } = stroke;
      if (points.length < 2) {
        return;
      }
      if (points.length === 2) {
        const [start, end] = points;
        const age = decay > 0 ? clamp(1 - (now - end.time) / decay, 0, 1) : 1;
        if (age <= 0) {
          return;
        }
        ctx.beginPath();
        ctx.moveTo(start.x, start.y);
        ctx.lineTo(end.x, end.y);
        ctx.globalAlpha = age;
        ctx.strokeStyle = color;
        ctx.lineWidth = end.width;
        ctx.stroke();
        return;
      }
      for (let i = 1; i < points.length - 1; i++) {
        const prev = points[i - 1];
        const curr = points[i];
        const next = points[i + 1];
        const age = decay > 0 ? clamp(1 - (now - curr.time) / decay, 0, 1) : 1;
        if (age <= 0) {
          continue;
        }
        const midPrevX = (prev.x + curr.x) / 2;
        const midPrevY = (prev.y + curr.y) / 2;
        const midNextX = (curr.x + next.x) / 2;
        const midNextY = (curr.y + next.y) / 2;
        const startX = prev.x + (midPrevX - prev.x) * smoothing;
        const startY = prev.y + (midPrevY - prev.y) * smoothing;
        const endX = next.x + (midNextX - next.x) * smoothing;
        const endY = next.y + (midNextY - next.y) * smoothing;
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.quadraticCurveTo(curr.x, curr.y, endX, endY);
        ctx.globalAlpha = age;
        ctx.strokeStyle = color;
        ctx.lineWidth = curr.width;
        ctx.stroke();
      }
    };

    const draw = () => {
      const now = performance.now();
      const { width, height } = sizeRef.current;
      ctx.clearRect(0, 0, width, height);
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.globalCompositeOperation = blend;

      for (const stroke of strokesRef.current) {
        if (decay > 0) {
          while (
            stroke.points.length > 0 &&
            now - stroke.points[0].time > decay
          ) {
            stroke.points.shift();
          }
        }
        drawStroke(stroke, now);
      }

      strokesRef.current = strokesRef.current.filter(
        (stroke) => stroke.points.length > 0
      );

      if (!paused) {
        rafRef.current = requestAnimationFrame(draw);
      }
    };

    if (!paused) {
      rafRef.current = requestAnimationFrame(draw);
    }

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
      resizeObserver.disconnect();
      container.removeEventListener("pointermove", handlePointerMove);
      container.removeEventListener("pointerleave", handlePointerLeave);
    };
  }, [
    blend,
    clearOnLeave,
    color,
    decay,
    isMounted,
    lineWidth,
    paused,
    smoothing,
    taper,
  ]);

  return (
    <div className={cn("relative", className)} ref={containerRef}>
      {children}
      {isMounted ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        >
          <canvas className="h-full w-full" ref={canvasRef} />
        </div>
      ) : null}
    </div>
  );
};

