  });

  it("formats a duration with a restricted unit set", () => {
    expect(formatDuration(90, ["minutes", "seconds"])).toBe("01:30");
  });

  it("falls back to the default units for an empty units array", () => {
    expect(formatDuration(61, [])).toBe("00:01:01");
  });
